def _clone_streaming_state(state):
    """Deep-copy a moshi streaming-state dict, cloning any tensors so the
    snapshot is independent of further mutations.

    `get_streaming_state()` returns live references to the module's internal
    buffers; without cloning, the very first inference step would scribble
    over our supposed snapshot. We only need to call this once per container
    (in setup) — `set_streaming_state_inplace` then copies INTO module
    buffers without mutating the source, so subsequent restores reuse the
    same snapshot dict directly.
    """
    import torch

    if isinstance(state, dict):
        return {k: _clone_streaming_state(v) for k, v in state.items()}
    if isinstance(state, list):
        return [_clone_streaming_state(x) for x in state]
    if isinstance(state, tuple):
        return tuple(_clone_streaming_state(x) for x in state)
    if isinstance(state, torch.Tensor):
        return state.clone().detach()
    return state  # primitives (int, float, bool, str, None)


