def _clone_streaming_state(state):
    """Deep-copy a moshi streaming-state structure, cloning any tensors so
    the snapshot is independent of further mutations.

    `get_streaming_state()` returns `{module_name: _StateClassInstance}`
    where each value is a dataclass holding the module's live tensors and
    nested state. `set_streaming_state()` REPLACES `module._streaming_state`
    with whatever instance we hand it, so subsequent inference mutates the
    snapshot's tensors in place. We must deep-clone before each restore.
    """
    import dataclasses

    import torch

    if isinstance(state, torch.Tensor):
        return state.clone().detach()
    if isinstance(state, dict):
        return {k: _clone_streaming_state(v) for k, v in state.items()}
    if isinstance(state, list):
        return [_clone_streaming_state(x) for x in state]
    if isinstance(state, tuple):
        return tuple(_clone_streaming_state(x) for x in state)
    if dataclasses.is_dataclass(state) and not isinstance(state, type):
        # _LMGenState, _MimiState, _TransformerState etc. — recreate the
        # same dataclass with each field deep-cloned.
        kwargs = {
            f.name: _clone_streaming_state(getattr(state, f.name))
            for f in dataclasses.fields(state)
        }
        return type(state)(**kwargs)
    return state  # primitives (int, float, bool, str, None)

